<template>
  <section class="friends-container">
    <header class="friends-header">
      <div><p class="eyebrow">SOCIAL GRAPH / FRIENDS</p><h1>Những người <em>cùng gu.</em></h1><p>Tìm bạn bè, kết nối và chuẩn bị cho những phòng nghe riêng của LuNu.</p></div>
      <div class="friends-count"><strong>{{ friendItems.length }}</strong><span>connections</span></div>
    </header>

    <div class="friends-grid">
      <section class="search-card glass-panel">
        <div class="card-heading"><div><span class="panel-kicker">DISCOVER PEOPLE</span><h2>Tìm người trên LuNu</h2></div><span class="card-number">01</span></div>
        <div class="search-box"><span>⌕</span><input v-model.trim="searchQuery" placeholder="Tìm bằng username hoặc tên hiển thị..." @input="searchUsersDebounced" /><button v-if="searchQuery" type="button" aria-label="Xóa tìm kiếm" @click="clearSearch">×</button></div>
        <div v-if="isSearching" class="inline-state">Đang tìm kiếm...</div>
        <div v-else-if="searchQuery.length >= 2 && !searchResults.length" class="inline-state">Không tìm thấy user phù hợp.</div>
        <div v-else class="person-list">
          <article v-for="user in searchResults" :key="user.id" class="person-row"><div class="person-avatar"><img v-if="user.avatar_url" :src="user.avatar_url" :alt="user.display_name" /><span v-else>{{ (user.display_name || user.username || 'U').slice(0, 1).toUpperCase() }}</span></div><div class="person-copy"><strong>{{ user.display_name || user.username }}</strong><span>@{{ user.username }}</span><small v-if="user.bio">{{ user.bio }}</small></div><button type="button" class="person-action" :disabled="pendingIds.has(String(user.id))" @click="sendRequest(user.id)">{{ pendingIds.has(String(user.id)) ? 'Đã gửi' : 'Kết bạn' }}</button></article>
        </div>
        <div v-if="!searchQuery" class="search-empty"><span>◌</span><p>Nhập ít nhất 2 ký tự để bắt đầu tìm kiếm.</p></div>
      </section>

      <section class="requests-card glass-panel">
        <div class="card-heading"><div><span class="panel-kicker">CONNECTIONS</span><h2>Lời mời & bạn bè</h2></div><button type="button" class="quiet-btn" @click="loadFriends">↻</button></div>
        <div v-if="incoming.length" class="request-section"><div class="subheading"><span>LỜI MỜI ĐẾN</span><b>{{ incoming.length }}</b></div><article v-for="item in incoming" :key="item.id" class="person-row"><div class="person-avatar"><img v-if="item.other_user?.avatar_url" :src="item.other_user.avatar_url" :alt="item.other_user.display_name" /><span v-else>{{ (item.other_user?.display_name || item.other_user?.username || 'U').slice(0, 1).toUpperCase() }}</span></div><div class="person-copy"><strong>{{ item.other_user?.display_name || item.other_user?.username }}</strong><span>@{{ item.other_user?.username }} muốn kết bạn</span></div><div class="request-actions"><button type="button" class="accept-btn" @click="acceptRequest(item.id)">Nhận</button><button type="button" class="reject-btn" @click="rejectRequest(item.id)">Bỏ</button></div></article></div>
        <div v-if="outgoing.length" class="request-section"><div class="subheading"><span>ĐÃ GỬI</span><b>{{ outgoing.length }}</b></div><article v-for="item in outgoing" :key="item.id" class="person-row"><div class="person-avatar"><img v-if="item.other_user?.avatar_url" :src="item.other_user.avatar_url" :alt="item.other_user.display_name" /><span v-else>{{ (item.other_user?.display_name || item.other_user?.username || 'U').slice(0, 1).toUpperCase() }}</span></div><div class="person-copy"><strong>{{ item.other_user?.display_name || item.other_user?.username }}</strong><span>@{{ item.other_user?.username }} · Đang chờ</span></div><button type="button" class="person-action muted" @click="cancelRequest(item.id)">Hủy</button></article></div>
        <div class="request-section friends-section"><div class="subheading"><span>BẠN BÈ</span><b>{{ accepted.length }}</b></div><article v-for="item in accepted" :key="item.id" class="person-row"><div class="presence-avatar"><div class="person-avatar"><img v-if="item.other_user?.avatar_url" :src="item.other_user.avatar_url" :alt="item.other_user.display_name" /><span v-else>{{ (item.other_user?.display_name || item.other_user?.username || 'U').slice(0, 1).toUpperCase() }}</span></div><i></i></div><div class="person-copy"><strong>{{ item.other_user?.display_name || item.other_user?.username }}</strong><span>@{{ item.other_user?.username }}</span></div><button type="button" class="person-action muted" @click="removeFriendship(item.other_user?.id)">Xóa</button></article><div v-if="!accepted.length" class="small-empty">Bạn chưa có kết nối nào.</div></div>
      </section>

      <section class="privacy-card glass-panel">
        <div class="card-heading"><div><span class="panel-kicker">PRIVACY / CONTROL</span><h2>Quyền riêng tư</h2></div><span class="card-number">03</span></div>
        <p class="privacy-intro">Bạn kiểm soát cách người khác tìm thấy và tương tác với mình.</p>
        <form class="privacy-form" @submit.prevent="savePrivacy"><label><span>AI ĐƯỢC GỬI LỜI MỜI KẾT BẠN</span><select v-model="privacy.allow_friend_requests"><option value="everyone">Mọi người</option><option value="friends_of_friends">Bạn của bạn bè</option><option value="nobody">Không ai</option></select></label><label><span>AI ĐƯỢC NHẮN TIN</span><select v-model="privacy.allow_direct_messages"><option value="friends">Chỉ bạn bè</option><option value="room_members">Người cùng phòng</option><option value="nobody">Không ai</option></select></label><label class="toggle-row"><span>Hiển thị trạng thái online</span><input v-model="privacy.show_online_status" type="checkbox" /><i></i></label><label class="toggle-row"><span>Hiển thị phòng đang tham gia</span><input v-model="privacy.show_current_room" type="checkbox" /><i></i></label><button type="submit" class="secondary-btn" :disabled="isSavingPrivacy">{{ isSavingPrivacy ? 'Đang lưu...' : 'Lưu quyền riêng tư' }}</button></form>
      </section>
    </div>
  </section>
</template>

<script setup>
import { computed, onMounted, onBeforeUnmount, ref } from 'vue';
import { acceptFriendRequest, cancelFriendRequest, getFriends, getPrivacySettings, rejectFriendRequest, removeFriend, searchUsers, sendFriendRequest, updatePrivacySettings } from '../services/api';
import { useToast } from '../composables/useToast';

const { showToast } = useToast();
const searchQuery = ref(''); const searchResults = ref([]); const friendItems = ref([]); const isSearching = ref(false); const isSavingPrivacy = ref(false); const pendingIds = ref(new Set());
const privacy = ref({ allow_friend_requests: 'everyone', allow_direct_messages: 'friends', show_online_status: true, show_current_room: false });
let searchTimer = null;
const accepted = computed(() => friendItems.value.filter((item) => item.status === 'accepted'));
const incoming = computed(() => friendItems.value.filter((item) => item.status === 'pending' && item.direction === 'incoming'));
const outgoing = computed(() => friendItems.value.filter((item) => item.status === 'pending' && item.direction === 'outgoing'));

const loadFriends = async () => { try { const response = await getFriends(); friendItems.value = response.items || []; } catch (error) { showToast(error.message || 'Không thể tải danh sách bạn bè.', { type: 'warning' }); } };
const loadPrivacy = async () => { try { const response = await getPrivacySettings(); privacy.value = { ...privacy.value, ...(response.settings || {}) }; } catch (error) { showToast(error.message || 'Chưa thể tải quyền riêng tư.', { type: 'warning' }); } };
const runSearch = async () => { if (searchQuery.value.length < 2) { searchResults.value = []; return; } isSearching.value = true; try { searchResults.value = await searchUsers(searchQuery.value); } catch (error) { showToast(error.message || 'Không thể tìm user.', { type: 'error' }); } finally { isSearching.value = false; } };
const searchUsersDebounced = () => { window.clearTimeout(searchTimer); searchTimer = window.setTimeout(runSearch, 260); };
const clearSearch = () => { searchQuery.value = ''; searchResults.value = []; };
const sendRequest = async (userId) => { const key = String(userId); pendingIds.value = new Set([...pendingIds.value, key]); try { const response = await sendFriendRequest(userId); showToast(response.message || 'Đã gửi lời mời.', { type: 'success' }); await loadFriends(); } catch (error) { showToast(error.message || 'Không thể gửi lời mời.', { type: 'error' }); pendingIds.value.delete(key); pendingIds.value = new Set(pendingIds.value); } };
const mutateFriendship = async (action, id, successMessage) => { try { const response = await action(id); showToast(response.message || successMessage, { type: 'success' }); await loadFriends(); } catch (error) { showToast(error.message || 'Không thể cập nhật quan hệ.', { type: 'error' }); } };
const acceptRequest = (id) => mutateFriendship(acceptFriendRequest, id, 'Đã chấp nhận lời mời.');
const rejectRequest = (id) => mutateFriendship(rejectFriendRequest, id, 'Đã từ chối lời mời.');
const cancelRequest = (id) => mutateFriendship(cancelFriendRequest, id, 'Đã hủy lời mời.');
const removeFriendship = (id) => mutateFriendship(removeFriend, id, 'Đã hủy kết bạn.');
const savePrivacy = async () => { isSavingPrivacy.value = true; try { const response = await updatePrivacySettings(privacy.value); privacy.value = { ...privacy.value, ...(response.settings || {}) }; showToast(response.message || 'Đã lưu quyền riêng tư.', { type: 'success' }); } catch (error) { showToast(error.message || 'Không thể lưu quyền riêng tư.', { type: 'error' }); } finally { isSavingPrivacy.value = false; } };

onMounted(() => { loadFriends(); loadPrivacy(); });
onBeforeUnmount(() => window.clearTimeout(searchTimer));
</script>

<style scoped>
.friends-container { max-width: 1180px; margin: 0 auto; padding: 18px 0 90px; }.friends-header { display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; padding: 32px 0 34px; }.eyebrow, .panel-kicker, .card-kicker { color: var(--gold); font: 9px var(--font-mono); letter-spacing: 1.8px; }.friends-header h1 { margin-top: 12px; font: 500 clamp(40px, 5vw, 62px)/.95 var(--font-display); letter-spacing: -2px; }.friends-header h1 em { color: var(--gold); font-style: italic; }.friends-header p:last-child { max-width: 600px; margin-top: 15px; color: var(--text-sub); font-size: 12px; line-height: 1.6; }.friends-count { display: flex; flex-direction: column; align-items: flex-end; }.friends-count strong { color: var(--gold-bright); font: 500 38px var(--font-display); }.friends-count span { color: var(--text-faint); font: 8px var(--font-mono); letter-spacing: 1.3px; text-transform: uppercase; }.friends-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 15px; }.search-card, .requests-card, .privacy-card { padding: clamp(18px, 3vw, 28px); border-radius: 19px; }.search-card { min-height: 470px; }.privacy-card { grid-column: 1 / -1; }.card-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; margin-bottom: 22px; }.card-heading h2 { margin-top: 8px; color: var(--text-main); font: 500 24px var(--font-display); }.card-number { color: var(--text-faint); font: 10px var(--font-mono); }.search-box { display: flex; align-items: center; gap: 9px; padding: 10px 12px; border: 1px solid var(--hairline); border-radius: 11px; background: rgba(3,5,9,.32); }.search-box > span { color: var(--gold); font-size: 20px; }.search-box input { flex: 1; min-width: 0; border: 0; outline: 0; background: transparent; color: var(--text-main); font-size: 11px; }.search-box button { border: 0; background: transparent; color: var(--text-faint); cursor: pointer; font-size: 20px; }.person-list { display: grid; gap: 4px; margin-top: 14px; }.person-row { display: flex; align-items: center; gap: 10px; min-width: 0; padding: 10px 7px; border-bottom: 1px solid rgba(255,255,255,.045); }.person-avatar, .presence-avatar { position: relative; flex: 0 0 auto; }.person-avatar { display: grid; place-items: center; width: 36px; height: 36px; overflow: hidden; border-radius: 12px; background: linear-gradient(135deg, var(--violet), var(--gold)); color: #171218; font: 800 11px var(--font-mono); }.person-avatar img { width: 100%; height: 100%; object-fit: cover; }.person-copy { display: flex; flex: 1; flex-direction: column; min-width: 0; }.person-copy strong { overflow: hidden; color: var(--text-main); text-overflow: ellipsis; white-space: nowrap; font-size: 11px; }.person-copy span { margin-top: 3px; overflow: hidden; color: var(--text-faint); text-overflow: ellipsis; white-space: nowrap; font: 8px var(--font-mono); }.person-copy small { margin-top: 5px; overflow: hidden; color: var(--text-sub); text-overflow: ellipsis; white-space: nowrap; font-size: 9px; }.person-action, .accept-btn, .reject-btn, .quiet-btn, .secondary-btn { border-radius: 8px; padding: 7px 9px; cursor: pointer; font-size: 9px; }.person-action { border: 1px solid rgba(245,185,122,.27); background: rgba(245,185,122,.08); color: var(--gold-bright); }.person-action.muted { border-color: var(--hairline); background: transparent; color: var(--text-faint); }.person-action:disabled { opacity: .6; cursor: wait; }.request-section { margin-top: 17px; }.subheading { display: flex; align-items: center; gap: 8px; margin-bottom: 4px; color: var(--text-faint); font: 8px var(--font-mono); letter-spacing: 1.2px; }.subheading b { display: inline-grid; place-items: center; min-width: 16px; height: 16px; border-radius: 5px; background: rgba(245,185,122,.12); color: var(--gold); font-size: 8px; }.request-actions { display: flex; gap: 4px; }.accept-btn { border: 1px solid rgba(139,224,190,.24); background: rgba(139,224,190,.09); color: var(--mint); }.reject-btn { border: 1px solid rgba(255,109,125,.23); background: transparent; color: var(--crimson); }.presence-avatar > i { position: absolute; right: -2px; bottom: -1px; width: 9px; height: 9px; border: 2px solid #171a25; border-radius: 50%; background: var(--mint); }.friends-section { border-top: 1px solid var(--hairline-soft); padding-top: 13px; }.small-empty, .inline-state { padding: 22px 5px; color: var(--text-faint); text-align: center; font-size: 10px; }.search-empty { display: grid; place-items: center; gap: 8px; min-height: 180px; color: var(--text-faint); text-align: center; }.search-empty span { color: var(--gold); font-size: 25px; }.search-empty p { font-size: 10px; }.quiet-btn { border: 1px solid var(--hairline); background: transparent; color: var(--text-sub); }.privacy-intro { margin: -8px 0 22px; color: var(--text-sub); font-size: 11px; }.privacy-form { display: grid; grid-template-columns: 1fr 1fr 1fr 1fr auto; align-items: end; gap: 13px; }.privacy-form label:not(.toggle-row) { display: grid; gap: 7px; }.privacy-form label > span { color: var(--text-faint); font: 8px var(--font-mono); letter-spacing: 1px; }.privacy-form select { width: 100%; box-sizing: border-box; padding: 11px; border: 1px solid var(--hairline); border-radius: 9px; outline: 0; background: rgba(3,5,9,.33); color: var(--text-main); font-size: 10px; }.toggle-row { position: relative; display: flex; align-items: center; justify-content: space-between; gap: 10px; min-height: 38px; padding: 0 10px; border: 1px solid var(--hairline-soft); border-radius: 9px; color: var(--text-sub); font-size: 9px; }.toggle-row input { position: absolute; opacity: 0; }.toggle-row i { position: relative; width: 28px; height: 16px; flex: 0 0 auto; border-radius: 99px; background: #393c47; transition: .2s; }.toggle-row i::after { position: absolute; top: 3px; left: 3px; width: 10px; height: 10px; border-radius: 50%; background: #a2a5b1; content: ''; transition: .2s; }.toggle-row input:checked + i { background: rgba(139,224,190,.35); }.toggle-row input:checked + i::after { left: 15px; background: var(--mint); }.secondary-btn { border: 1px solid rgba(139,224,190,.27); background: rgba(139,224,190,.08); color: var(--mint); white-space: nowrap; }.secondary-btn:disabled { opacity: .55; cursor: progress; }
@media (max-width: 900px) { .privacy-form { grid-template-columns: 1fr 1fr; }.privacy-form .secondary-btn { grid-column: 1 / -1; justify-self: start; } }
@media (max-width: 680px) { .friends-container { padding-bottom: 102px; }.friends-header { align-items: flex-start; flex-direction: column; padding-top: 20px; }.friends-count { align-items: flex-start; }.friends-grid { grid-template-columns: 1fr; }.privacy-card { grid-column: auto; }.privacy-form { grid-template-columns: 1fr; }.privacy-form .secondary-btn { grid-column: auto; width: 100%; }.person-row { padding-right: 0; padding-left: 0; }.request-actions { flex-direction: column; }.request-actions button { padding: 6px 8px; }.person-copy small { display: none; } }
</style>
